const inputData = $input.first()?.json || {};
const query = (inputData.query || '').toLowerCase().trim();

// Canonical member aliases
const memberAliases = {
  'scoups': 'S.COUPS', 's.coups': 'S.COUPS', 'coups': 'S.COUPS', 'cheol': 'S.COUPS', 'seungcheol': 'S.COUPS',
  'jeonghan': 'JEONGHAN', 'hannie': 'JEONGHAN',
  'joshua': 'JOSHUA', 'shua': 'JOSHUA', 'hong': 'JOSHUA',
  'jun': 'JUN', 'wen junhui': 'JUN', 'junhui': 'JUN',
  'hoshi': 'HOSHI', 'soonyoung': 'HOSHI', 'tiger': 'HOSHI',
  'wonwoo': 'WONWOO',
  'woozi': 'WOOZI', 'jihoon': 'WOOZI',
  'dk': 'DK', 'dokyeom': 'DK', 'seokmin': 'DK',
  'mingyu': 'MINGYU',
  'minghao': 'MINGHAO', 'the8': 'MINGHAO', 'myungho': 'MINGHAO', 'xuminghao': 'MINGHAO',
  'seungkwan': 'SEUNGKWAN', 'kwan': 'SEUNGKWAN', 'boo': 'SEUNGKWAN',
  'vernon': 'VERNON', 'hansol': 'VERNON',
  'dino': 'DINO', 'chan': 'DINO', 'lee chan': 'DINO',
  'unit': 'UNIT'
};

let detectedMembers = [];
for (const [alias, canonical] of Object.entries(memberAliases)) {
  const regex = new RegExp('\\b' + alias.replace('.', '\\.') + '\\b', 'i');
  if (regex.test(query) && !detectedMembers.includes(canonical)) {
    detectedMembers.push(canonical);
  }
}

// Intent flags
const shippingKeywords = ['shipping', 'sf', 'pf', 'pack', 'delivery', 'luzon', 'visayas', 'mindanao', 'courier', 'j&t', 'j and t', 'padala'];
const paymentKeywords = ['payment', 'mop', 'gcash', 'maya', 'maribank', 'downpayment', 'nrdp', 'deadline', 'bayad', 'transfer'];
const policyKeywords = ['kailan', 'schedule', 'sched', 'rules', 'shipout', 'ship out', 'days', 'araw', 'when'];

const isShipping = shippingKeywords.some(kw => query.includes(kw));
const isPayment = paymentKeywords.some(kw => query.includes(kw));
const isPolicy = policyKeywords.some(kw => query.includes(kw));

return {
  query,
  detectedMembers,
  isShipping,
  isPayment,
  isPolicy,
  rawInput: inputData
};

