const parsed = $('Parse Query Entities').first().json;
const query = (parsed.query || '').toLowerCase().trim();
const detectedMembers = parsed.detectedMembers || [];
const allProducts = $('Fetch All Products from DB').all().map(i => i.json);

function scoreProduct(prod) {
  let score = 0;
  const memberLower = (prod.member || '').toLowerCase();
  const nameLower = (prod.product_name || '').toLowerCase();
  const notesLower = (prod.notes || '').toLowerCase();
  const fullText = `${memberLower} ${nameLower} ${notesLower}`;

  // Member matching
  if (detectedMembers.length > 0) {
    if (detectedMembers.includes(prod.member)) {
      score += 50;
    } else {
      return 0;
    }
  }

  // Token matching (excluding stop words)
  const cleanQuery = query.replace(/[^\w\s]/g, ' ');
  const stopWords = ['and', 'the', 'for', 'via', 'with', 'magkano', 'ano', 'meron', 'available', 'po', 'ba', 'kayo', 'ni', 'sa', 'how', 'much', 'is', 'si', 'pa'];
  const queryTokens = cleanQuery.split(/\s+/).filter(t => t.length > 1 && !stopWords.includes(t));
  for (const token of queryTokens) {
    if (nameLower.includes(token)) score += 20;
    else if (notesLower.includes(token)) score += 10;
    else if (memberLower.includes(token)) score += 15;
  }

  // Specific album matching
  const albumPatterns = ['fml', 'sector 17', 'attacca', 'fts', 'face the sun', '17rh', '17 is right here', 'heaven', 'spill the feels', 'stf', 'an ode', 'henggarae', 'heng:garae', 'teen age', 'bss', 'shohikigen', 'v8', 'burstday', 'barbie', 'prince', 'digital code', 'carat land', 'caratland'];
  for (const alb of albumPatterns) {
    if (query.includes(alb) && fullText.includes(alb)) {
      score += 30;
    }
  }

  return score;
}

let scored = allProducts.map(p => ({ product: p, score: scoreProduct(p) }))
  .filter(item => item.score >= 40)
  .sort((a, b) => b.score - a.score);

let matchStatus = 'NOT_FOUND';
let matchedProducts = [];

if (scored.length === 1) {
  matchStatus = scored[0].product.stock === 0 ? 'OUT_OF_STOCK' : 'EXACT_MATCH';
  matchedProducts = [scored[0].product];
} else if (scored.length > 1) {
  if (scored[0].score >= scored[1].score + 15) {
    matchStatus = scored[0].product.stock === 0 ? 'OUT_OF_STOCK' : 'EXACT_MATCH';
    matchedProducts = [scored[0].product];
  } else {
    matchStatus = 'AMBIGUOUS_MATCH';
    matchedProducts = scored.slice(0, 5).map(s => s.product);
  }
} else if (detectedMembers.length === 1) {
  const memberProds = allProducts.filter(p => p.member === detectedMembers[0]);
  if (memberProds.length > 0) {
    matchStatus = 'AMBIGUOUS_MATCH';
    matchedProducts = memberProds;
  }
}

return {
  query,
  detectedMembers,
  matchStatus,
  matchedCount: matchedProducts.length,
  products: matchedProducts,
  isShippingInquiry: parsed.isShipping,
  isPaymentInquiry: parsed.isPayment,
  isPolicyInquiry: parsed.isPolicy,
  shippingRates: {
    luzon: { small: 79, medium: 144, large: 174 },
    visayas: { small: 74, medium: 134, large: 164 },
    mindanao: { small: 54, medium: 104, large: 144 },
    courier: "J&T Express (with ₱21 voucher included)"
  },
  packingFees: {
    small: "₱20 (1-10 PCs: toploader, chipboard, bubble wrap, bubble mailer)",
    medium: "₱25 (10-20 PCs / keychains: toploader, chipboard, bubble wrap, corrugated box)",
    large: "₱30 (albums: bubble wrap, chipboard, cardboard)"
  },
  paymentMethods: [
    { method: "GCash", account_number: "09XXXXXXXXX", account_name: "Store Owner" },
    { method: "Maya", account_number: "09XXXXXXXXX", account_name: "Store Owner" },
    { method: "MariBank", account_number: "XXXXXXXXXXXX", account_name: "Store Owner" }
  ],
  shopPolicies: {
    deliveryDays: "Monday–Wednesday only",
    paymentDeadline: "1 week from reservation",
    downpayment: "30% non-refundable downpayment (nrdp) required"
  }
};
